ee:message.ee:set-payload:
%dw 2.0
output application/json
var allGenres = readUrl("classpath://lastfm/tags.json" , "application/json")
var csvUsers = read(vars.csvFileContent as String as Binary as String, "application/csv")

// On recup un tableau avec uniquement tout les tags
var allGenresArray = flatten(csvUsers map () -> $.genres splitBy(",") map (item) -> trim(item))

// On s'assure que les tags existent
var filteredGenres = allGenresArray filter (genre) -> (allGenres.tags contains genre)

// On groupe les tags par genres
var groupedGenres = filteredGenres groupBy ((genre) -> genre)

// On compte le nb occurences par genres
var countedGenres = groupedGenres mapObject ((value, key) -> {
  (key): sizeOf(value)
})
---
(countedGenres pluck ((count, genre) -> {
  "genre": genre,
  "count": count
})
orderBy ((item) -> -item.count))[0 to 1]

%dw 2.0
output application/json

var csvFile = read(vars.csvFileContent as String as Binary as String, "application/csv")
---
{
  "date": vars.date,
  "genres": vars.genres map () -> $.genre,
  "users": csvFile map () -> {
    firstname: $.firstname,
    lastname: $.lastname,
    email: $.email,
    genres: $.genres splitBy(",") map (genre) -> trim(genre),
  },
  "tracks": payload
}
